//! Measured confidence per deciding construct: floor(100 x Wilson 95 % lower bound
//! of dev precision). Generated by eval/confidence.py from a-dev.csv (manifest sha256 06d8905d897ba1a8, 2026-10-29). Do not edit.

/// Sorted by construct id.
pub static TABLE: &[(&str, u8)] = &[
    ("cmd.chained-command", 70),
    ("path.directory-traversal", 64),
    ("sqli.boolean-tautology", 24),
    ("sqli.quote-breakout", 46),
    ("sqli.stacked-query", 18),
    ("sqli.union-select", 17),
    ("xss.dangerous-proto", 62),
    ("xss.event-handler", 75),
    ("xss.script-tag", 38),
];

/// The measured confidence of a construct, if it decided enough dev rows.
pub fn confidence(construct_id: &str) -> Option<u8> {
    TABLE.binary_search_by(|(k, _)| (*k).cmp(construct_id)).ok().map(|i| TABLE[i].1)
}
